local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/configuring/core/binds/ for more
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + C", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(
	mainMod .. " + M",
	hl.dsp.exec_cmd(home .. "/.config/rofi/powermenu/type-2/powermenu.sh")
)
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("killall -SIGUSR1 waybar"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + T", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + V", function()
	local ws = hl.get_active_workspace()
	local wins = hl.get_workspace_windows(ws.id)
	if not wins or #wins == 0 then return end

	local any_tiled = false
	for _, w in ipairs(wins) do
		if not w.floating then
			any_tiled = true
			break
		end
	end

	for _, w in ipairs(wins) do
		if any_tiled then
			if not w.floating then
				hl.dispatch(hl.dsp.window.float({ action = "on", window = "address:" .. tostring(w.address) }))
			end
		else
			if w.floating then
				hl.dispatch(hl.dsp.window.float({ action = "off", window = "address:" .. tostring(w.address) }))
			end
		end
	end
end)

-- Window transparency management
local window_opacities = {}
local transparency_step = 0.05
local min_opacity = 0.10
local max_opacity = 1.00

local function adjust_active_transparency(delta_opacity)
	local win = hl.get_active_window()
	if not win then return end
	local addr = tostring(win.address)
	local current_opacity = window_opacities[addr] or 1.0
	local new_opacity = math.max(min_opacity, math.min(max_opacity, current_opacity + delta_opacity))
	new_opacity = math.floor(new_opacity * 100 + 0.5) / 100

	if new_opacity >= 1.0 then
		window_opacities[addr] = 1.0
		hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity", value = "1.0" }))
		hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity_override", value = "false" }))
		hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity_inactive", value = "1.0" }))
		hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity_inactive_override", value = "false" }))
	else
		window_opacities[addr] = new_opacity
		local val_str = string.format("%.2f", new_opacity)
		hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity", value = val_str }))
		hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity_override", value = "true" }))
		hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity_inactive", value = val_str }))
		hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity_inactive_override", value = "true" }))
	end
end

-- Ctrl + Alt + Up: Increase opacity (more solid)
hl.bind("CTRL + ALT + up", function()
	adjust_active_transparency(transparency_step)
end, { repeating = true })

-- Ctrl + Alt + Down: Decrease opacity (more transparent)
hl.bind("CTRL + ALT + down", function()
	adjust_active_transparency(-transparency_step)
end, { repeating = true })

-- Ctrl + Alt + Enter / Return: Reset transparency for current active window
local function reset_current_transparency()
	local win = hl.get_active_window()
	if not win then return end
	local addr = tostring(win.address)
	window_opacities[addr] = nil
	hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity", value = "1.0" }))
	hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity_override", value = "false" }))
	hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity_inactive", value = "1.0" }))
	hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity_inactive_override", value = "false" }))
end
hl.bind("CTRL + ALT + Return", reset_current_transparency)

-- Ctrl + Alt + \: Reset transparency for all windows
local function reset_all_transparency()
	local wins = hl.get_windows()
	if wins then
		for _, w in ipairs(wins) do
			local addr = tostring(w.address)
			hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity", value = "1.0" }))
			hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity_override", value = "false" }))
			hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity_inactive", value = "1.0" }))
			hl.dispatch(hl.dsp.window.set_prop({ window = "address:" .. addr, prop = "opacity_inactive_override", value = "false" }))
		end
	end
	window_opacities = {}
end
hl.bind("CTRL + ALT + backslash", reset_all_transparency)

